  AS entry(id text, ruby jsonb, "formerNames" jsonb, "needsReview" boolean);
INSERT INTO "ski_resort_ruby_segments" ("skiResortId", "position", "text", "ruby")
SELECT source.id, segment.ordinality - 1, segment.value->>'text', segment.value->>'ruby'
FROM reading_import_source source JOIN "ski_resorts" resort ON resort.id = source.id
CROSS JOIN LATERAL jsonb_array_elements(source.ruby) WITH ORDINALITY AS segment(value, ordinality);
INSERT INTO "ski_resort_former_names" ("skiResortId", "position", "name", "reading")
SELECT source.id, entry.ordinality - 1, entry.value->>'name', entry.value->>'reading'
FROM reading_import_source source JOIN "ski_resorts" resort ON resort.id = source.id
CROSS JOIN LATERAL jsonb_array_elements(source."formerNames") WITH ORDINALITY AS entry(value, ordinality);
UPDATE "ski_resorts" resort SET "readingNeedsReview" = source."needsReview"
FROM reading_import_source source WHERE resort.id = source.id;
COMMIT;
